import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); K = int(data[1])
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(n - 1):
        u = int(data[p]); v = int(data[p + 1]); p += 2
        adj[u].append(v); adj[v].append(u)
    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)
    order.reverse()
    order.pop()  # drop the root, it is processed last in the reversed order
    depth = [0] * n
    for u in reversed(order):
        depth[u] = depth[parent[u]] + 1
    D = max(depth) if n > 1 else 0

    def cuts(H):
        h = [0] * n
        c = 0
        for v in order:
            pv = parent[v]
            if h[v] == H - 1 and pv != 0:
                c += 1
            elif h[v] + 1 > h[pv]:
                h[pv] = h[v] + 1
        return c

    if n == 1:
        print(0)
        return
    lo, hi = 1, D
    while lo < hi:
        mid = (lo + hi) // 2
        if cuts(mid) <= K:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

